import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import * as signalR from '@microsoft/signalr';
import { orderService, metricsService, productService, userService } from '@/services';
import { MetricType } from '@/types';
import { STATUS_COLORS, STATUS_LABELS, DEFAULT_PRODUCTS } from '@/constants';

interface Robot {
  id: string;
  name: string;
  x: number;
  y: number;
  battery: number;
  status: 'Idle' | 'Moving' | 'Error' | 'Charging';
}

interface DashboardOrder {
  id: string;
  date: string;
  total: number;
  status: 'Pending' | 'Confirmed' | 'Shipped' | 'Delivered' | 'Cancelled';
  station: string;
  items: Array<{ name: string; quantity: number; price: number }>;
}

export function DashboardPage() {
  const [robots, setRobots] = useState<Robot[]>([
    { id: 'AMR-01', name: 'AMR-01 (Mantis)', x: 2, y: 3, battery: 84, status: 'Moving' },
    { id: 'AMR-02', name: 'AMR-02 (Scarab)', x: 7, y: 1, battery: 95, status: 'Idle' },
    { id: 'AMR-03', name: 'AMR-03 (Hornet)', x: 0, y: 9, battery: 18, status: 'Charging' }
  ]);
  const [signalRConnected, setSignalRConnected] = useState(false);

  const [loading, setLoading] = useState(true);
  const [productsCount, setProductsCount] = useState(0);
  const [pendingOrders, setPendingOrders] = useState<DashboardOrder[]>([]);
  const [totalStock, setTotalStock] = useState(0);
  const [usersCount, setUsersCount] = useState(0);

  const getProductName = (productId: string) => {
    const prod = DEFAULT_PRODUCTS.find(p => p.id === productId);
    return prod ? prod.name : `Sß║ún phß║⌐m (${productId.substring(0, 8)})`;
  };

  const loadDashboardData = async () => {
    setLoading(true);
    try {
      // Fetch products
      const prods = await productService.getProducts().catch(() => []);
      setProductsCount(prods.length);
      const stockSum = prods.reduce((sum: number, p) => sum + (p.stockQuantity || 0), 0);
      
      // Fetch pending orders
      const apiOrders = await orderService.getPendingOrders().catch(() => []);
      const mapped: DashboardOrder[] = apiOrders.map((o: any) => ({
        id: o.id,
        date: o.createdAt ? o.createdAt.split('T')[0] : new Date().toISOString().split('T')[0],
        total: o.totalAmount,
        status: 'Pending' as const,
        station: o.deliveryNodeId || 'Khu vß╗▒c nhß║¡n',
        items: o.items ? o.items.map((item: any) => ({
          name: getProductName(item.productId),
          quantity: item.quantity,
          price: item.price
        })) : []
      }));
      setPendingOrders(mapped.slice(0, 5));

      // Fetch users
      const usersList = await userService.getAllUsers().catch(() => []);
      setUsersCount(usersList.length);

      // Fetch InventoryCount metric from service
      try {
        const metric = await metricsService.getLatestMetric('WH001', MetricType.InventoryCount);
        setTotalStock(metric.metricValue);
      } catch {
        setTotalStock(stockSum || 489);
      }
    } catch (err) {
      console.error('Error loading dashboard data:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadDashboardData();

    // SignalR Connection
    const connection = new signalR.HubConnectionBuilder()
      .withUrl('http://localhost:5002/hubs/robot-tracking')
      .withAutomaticReconnect()
      .build();

    connection.start()
      .then(() => {
        setSignalRConnected(true);
        connection.on('ReceiveRobotLocation', (updatedRobot: Robot) => {
          setRobots(prev => {
            const idx = prev.findIndex(r => r.id === updatedRobot.id);
            if (idx > -1) {
              const clone = [...prev];
              clone[idx] = { ...clone[idx], ...updatedRobot };
              return clone;
            }
            return [...prev, updatedRobot];
          });
        });
      })
      .catch((err: any) => {
        console.warn('SignalR offline on Dashboard. Running with static fleet representation.', err);
      });

    return () => {
      connection.stop().catch(() => {});
    };
  }, []);

  const cardConfig = [
    { title: 'Sß║ún phß║⌐m trong kho', value: productsCount.toString(), change: 'Danh mß╗Ñc sß║ún phß║⌐m hiß╗çn c├│', icon: '≡ƒôª', iconColor: 'text-blue-400' },
    { title: '─É╞ín h├áng chß╗¥ duyß╗çt', value: pendingOrders.length.toString(), change: 'Cß║ºn ph├¬ duyß╗çt tß╗½ admin', icon: '≡ƒôï', iconColor: 'text-purple-400' },
    { title: 'Robot AMR hoß║ít ─æß╗Öng', value: `${robots.filter(r => r.status !== 'Error').length}/${robots.length}`, change: '─Éß╗Öi robot tß╗▒ h├ánh', icon: '≡ƒñû', iconColor: 'text-emerald-400' },
    { title: 'Tß╗òng sß╗æ l╞░ß╗úng tß╗ôn kho', value: totalStock.toLocaleString(), change: `Sß╗æ l╞░ß╗úng tß╗½ ${usersCount} t├ái khoß║ún`, icon: '≡ƒæÑ', iconColor: 'text-orange-400' }
  ];

  const statusColors = STATUS_COLORS;
  const statusLabels = STATUS_LABELS;

  if (loading) {
    return (
      <div className="min-h-screen bg-slate-50 text-slate-800 font-sans p-6 md:p-10 flex flex-col items-center justify-center space-y-4">
        <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-brand-600"></div>
        <p className="text-slate-500 text-xs font-semibold">─Éang tß╗òng hß╗úp dß╗» liß╗çu bß║úng ─æiß╗üu khiß╗ân...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 font-sans p-6 md:p-10 space-y-8">
      {/* Header */}
      <div className="flex items-center justify-between border-b border-slate-200 pb-6">
        <div>
          <h1 className="text-3xl font-heading font-extrabold text-slate-900 tracking-tight flex items-center gap-2">
            <span>≡ƒôè</span> Bß║úng ─æiß╗üu khiß╗ân admin
          </h1>
          <p className="mt-1 text-sm text-slate-505">Gi├ím s├ít hoß║ít ─æß╗Öng kho h├áng, robot AMR v├á ph├ón t├¡ch kinh doanh</p>
        </div>
        <button
          onClick={loadDashboardData}
          className="px-4 py-2 bg-white hover:bg-slate-100 text-slate-700 text-xs font-bold rounded-xl border border-slate-200 transition-colors"
        >
          ≡ƒöä L├ám mß╗¢i
        </button>
      </div>

      {/* Cards stats grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {cardConfig.map((c, i) => (
          <div key={i} className="bg-white p-6 rounded-2xl border border-slate-200/80 shadow-sm flex items-center justify-between transition-all hover:border-slate-300">
            <div className="space-y-2">
              <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">{c.title}</p>
              <h3 className="text-2xl font-heading font-black text-slate-900">{c.value}</h3>
              <p className="text-[11px] text-slate-500 font-medium">{c.change}</p>
            </div>
            <div className={`w-12 h-12 rounded-xl flex items-center justify-center text-2xl bg-slate-50 border border-slate-200/60 ${c.iconColor}`}>
              {c.icon}
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Main analytical status */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white rounded-2xl border border-slate-200/80 p-6 shadow-sm">
            <div className="flex items-center justify-between border-b border-slate-100 pb-4 mb-4">
              <h3 className="font-heading font-bold text-slate-900 flex items-center gap-2">
                <span>≡ƒôê</span> Biß╗âu ─æß╗ô hoß║ít ─æß╗Öng tuß║ºn n├áy
              </h3>
              <span className="text-[10px] font-bold text-slate-400 uppercase">─É╞ín vß╗ï: ─É╞ín h├áng</span>
            </div>
            
            {/* SVG custom bar graph */}
            <div className="h-64 flex items-end justify-between pt-6 gap-2">
              {[
                { day: 'Th 2', val: 5, pct: 40 },
                { day: 'Th 3', val: 8, pct: 60 },
                { day: 'Th 4', val: 7, pct: 50 },
                { day: 'Th 5', val: 12, pct: 80 },
                { day: 'Th 6', val: 15, pct: 100 },
                { day: 'Th 7', val: 9, pct: 70 },
                { day: 'CN', val: 4, pct: 30 }
              ].map((bar, i) => (
                <div key={i} className="flex-1 flex flex-col items-center gap-2 group cursor-pointer">
                  <div className="w-full relative flex justify-center h-48 items-end">
                    {/* Tooltip */}
                    <span className="absolute bottom-full mb-1 opacity-0 group-hover:opacity-100 transition-opacity bg-slate-900 text-white text-[10px] font-bold py-1 px-2 rounded-lg pointer-events-none z-10 whitespace-nowrap shadow-md">
                      {bar.val} ─æ╞ín
                    </span>
                    {/* Bar */}
                    <div 
                      style={{ height: `${bar.pct}%` }}
                      className="w-8 sm:w-12 rounded-t-lg bg-brand-500/80 transition-all duration-300 group-hover:brightness-110 group-hover:shadow-lg group-hover:shadow-brand-500/10"
                    ></div>
                  </div>
                  <span className="text-xs font-bold text-slate-400">{bar.day}</span>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Sidebar panels */}
        <div className="space-y-6">
          <div className="bg-white text-slate-800 rounded-2xl p-6 shadow-sm border border-slate-200/80 space-y-6">
            <div className="flex items-center justify-between">
              <h3 className="font-heading font-bold text-slate-900 flex items-center gap-2">
                <span>≡ƒñû</span> Trß║íng th├íi Robot AMR
              </h3>
              <span className={`w-2.5 h-2.5 rounded-full ${signalRConnected ? 'bg-emerald-500 animate-pulse' : 'bg-amber-500'}`}></span>
            </div>
            <div className="space-y-4">
              {robots.map((r, idx) => (
                <div key={idx} className="flex items-center justify-between border-b border-slate-100 pb-3 last:border-0 last:pb-0">
                  <div className="space-y-1">
                    <h4 className="text-sm font-bold text-slate-900">{r.name}</h4>
                    <span className={`inline-block text-[9px] font-bold px-2 py-0.5 rounded-full border ${
                      r.status === 'Idle' ? 'border-emerald-250 text-emerald-700 bg-emerald-50' :
                      r.status === 'Moving' ? 'border-brand-200 text-brand-700 bg-brand-50' :
                      r.status === 'Charging' ? 'border-amber-200 text-amber-700 bg-amber-50' : 'border-red-200 text-red-700 bg-red-50'
                    }`}>
                      {r.status === 'Idle' ? 'Rß║únh (Idle)' : r.status === 'Moving' ? '─Éang chß║íy' : r.status === 'Charging' ? '─Éang sß║íc' : 'Lß╗ùi'}
                    </span>
                  </div>
                  <div className="text-right">
                    <span className={`font-mono text-xs font-bold ${r.battery < 20 ? 'text-red-600' : 'text-slate-500'}`}>
                      {Math.round(r.battery)}% Pin
                    </span>
                  </div>
                </div>
              ))}
            </div>
            <Link
              to="/admin/inventory"
              className="block text-center w-full py-2.5 bg-slate-50 hover:bg-slate-105 text-brand-650 hover:text-brand-700 text-xs font-bold rounded-xl border border-slate-200 transition-colors"
            >
              ≡ƒù║∩╕Å S╞í ─æß╗ô & ─æiß╗üu phß╗æi AMR
            </Link>
          </div>
        </div>
      </div>

      {/* Recent Orders log */}
      <div className="bg-white rounded-2xl border border-slate-200/80 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-slate-100 flex items-center justify-between">
          <h3 className="font-heading font-bold text-slate-900 flex items-center gap-2">
            <span>≡ƒôï</span> ─É╞ín h├áng mß╗¢i ─æß║╖t chß╗¥ duyß╗çt
          </h3>
          <Link to="/admin/orders" className="text-brand-650 text-xs font-bold hover:underline">
            Xem tß║Ñt cß║ú ─æ╞ín h├áng chß╗¥ duyß╗çt ΓåÆ
          </Link>
        </div>
        
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse text-sm">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200 text-slate-500 font-bold">
                <th className="p-4">M├ú ─æ╞ín</th>
                <th className="p-4">Ng├áy tß║ío</th>
                <th className="p-4">Trß║ím giao</th>
                <th className="p-4">Tß╗òng tiß╗ün</th>
                <th className="p-4">Trß║íng th├íi</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-slate-650 font-medium">
              {pendingOrders.map((o) => (
                <tr key={o.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="p-4 font-bold text-slate-900">{o.id}</td>
                  <td className="p-4">{o.date}</td>
                  <td className="p-4 font-bold text-slate-700">{o.station}</td>
                  <td className="p-4 text-slate-900 font-bold">{o.total.toLocaleString()}─æ</td>
                  <td className="p-4">
                    <span className={`px-2.5 py-0.5 rounded-full text-xs font-bold border ${statusColors[o.status] || 'bg-slate-50 border-slate-200'}`}>
                      {statusLabels[o.status] || o.status}
                    </span>
                  </td>
                </tr>
              ))}
              {pendingOrders.length === 0 && (
                <tr>
                  <td colSpan={5} className="p-8 text-center text-slate-400 italic">Kh├┤ng c├│ ─æ╞ín ─æß║╖t h├áng n├áo gß║ºn ─æ├óy</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import * as signalR from '@microsoft/signalr';
import { secureRandom } from '@/utils/crypto';

interface Robot {
  id: string;
  name: string;
  x: number;
  y: number;
  battery: number;
  status: 'Idle' | 'Moving' | 'Error' | 'Charging';
  destination?: string;
}

// Grid sizes (10x10 grid)
const gridRows = 10;
const gridCols = 10;

// Shelves locations (obstacles)
const shelves = [
  { x: 2, y: 1 }, { x: 2, y: 2 },
  { x: 4, y: 4 }, { x: 4, y: 5 }, { x: 5, y: 4 }, { x: 5, y: 5 },
  { x: 7, y: 7 }, { x: 7, y: 8 }, { x: 8, y: 7 }, { x: 8, y: 8 }
];

// Delivery stations positions
const deliveryStations = [
  { id: 'ST01', name: 'Trß║ím A', x: 0, y: 2 },
  { id: 'ST02', name: 'Trß║ím B', x: 9, y: 2 },
  { id: 'ST03', name: 'Trß║ím C', x: 0, y: 6 },
  { id: 'ST04', name: 'Trß║ím D', x: 9, y: 6 },
  { id: 'ST05', name: 'Trß║ím E', x: 5, y: 0 }
];

// Charging docks
const chargingDocks = [
  { x: 0, y: 9 }, { x: 1, y: 9 }
];

export function InventoryPage() {
  const [robots, setRobots] = useState<Robot[]>([
    { id: 'AMR-01', name: 'AMR-01 (Mantis)', x: 2, y: 3, battery: 84, status: 'Moving', destination: 'Trß║ím A' },
    { id: 'AMR-02', name: 'AMR-02 (Scarab)', x: 7, y: 1, battery: 95, status: 'Idle' },
    { id: 'AMR-03', name: 'AMR-03 (Hornet)', x: 0, y: 9, battery: 18, status: 'Charging' }
  ]);
  const [selectedRobot, setSelectedRobot] = useState<string | null>(null);
  const [signalRConnected, setSignalRConnected] = useState(false);

  useEffect(() => {
    // Attempt SignalR connection to backend AMR service
    const connection = new signalR.HubConnectionBuilder()
      .withUrl('http://localhost:5002/hubs/robot-tracking')
      .withAutomaticReconnect()
      .build();

    connection.start()
      .then(() => {
        setSignalRConnected(true);
        console.log('SignalR connected to AMR service');
        connection.on('ReceiveRobotLocation', (updatedRobot: Robot) => {
          setRobots(prev => {
            const idx = prev.findIndex(r => r.id === updatedRobot.id);
            if (idx > -1) {
              const clone = [...prev];
              clone[idx] = { ...clone[idx], ...updatedRobot };
              return clone;
            }
            return [...prev, updatedRobot];
          });
        });
      })
      .catch((err: any) => {
        console.warn('SignalR fallback. Operating in simulation mode.', err);
      });

    // Fallback simulation timer to make the robots move around
    const interval = setInterval(() => {
      if (signalRConnected) return; // Ignore simulation if real SignalR is online
      
      setRobots(prev => prev.map(robot => {
        if (robot.status === 'Moving') {
          let dx: number;
          let dy: number;
          if (robot.id === 'AMR-01') {
            // Target Trß║ím A (0,2)
            dx = Math.sign(0 - robot.x);
            dy = Math.sign(2 - robot.y);
          } else {
            // Random movement
            dx = Math.floor(secureRandom() * 3) - 1;
            dy = Math.floor(secureRandom() * 3) - 1;
          }

          let nextX = Math.max(0, Math.min(gridCols - 1, robot.x + dx));
          let nextY = Math.max(0, Math.min(gridRows - 1, robot.y + dy));

          // Check if shelf collision
          const collides = shelves.some(s => s.x === nextX && s.y === nextY);
          if (collides) {
            nextX = robot.x;
            nextY = robot.y;
          }

          // Arrive at destination check
          let status: 'Idle' | 'Moving' | 'Error' | 'Charging' = robot.status;
          let dest = robot.destination;
          if (robot.id === 'AMR-01' && nextX === 0 && nextY === 2) {
            status = 'Idle';
            dest = undefined;
          }

          return { ...robot, x: nextX, y: nextY, battery: Math.max(0, robot.battery - 0.5), status, destination: dest };
        } else if (robot.status === 'Idle' && secureRandom() < 0.05) {
          // Randomly trigger wandering
          return { ...robot, status: 'Moving', destination: 'Tuß║ºn tra kho' };
        } else if (robot.status === 'Charging') {
          // Recharge battery
          return { ...robot, battery: Math.min(100, robot.battery + 2) };
        }
        return robot;
      }));
    }, 2000);

    return () => {
      clearInterval(interval);
      connection.stop().catch(() => {});
    };
  }, [signalRConnected]);

  const commandRobotToMove = (_stationX: number, _stationY: number, label: string) => {
    if (!selectedRobot) return;
    setRobots(prev => prev.map(r => {
      if (r.id === selectedRobot) {
        return {
          ...r,
          status: 'Moving',
          destination: label,
          x: r.x, // Starts moving towards coordinates
          y: r.y
        };
      }
      return r;
    }));
    setSelectedRobot(null);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 font-sans p-6 md:p-10 space-y-8">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-slate-200 pb-6">
        <div>
          <h1 className="text-3xl font-heading font-extrabold text-slate-900 tracking-tight flex items-center gap-2">
            <span>≡ƒù║∩╕Å</span> Gi├ím s├ít Robot & Kho h├áng
          </h1>
          <p className="mt-1 text-sm text-slate-505">
            ─Éß╗ïnh vß╗ï robot AMR tr├¬n s╞í ─æß╗ô l╞░ß╗¢i nh├á kho thß╗¥i gian thß╗▒c.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <span className={`w-3 h-3 rounded-full ${signalRConnected ? 'bg-emerald-500 animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.4)]' : 'bg-amber-500 shadow-[0_0_8px_rgba(245,158,11,0.4)]'}`}></span>
          <span className="text-xs font-bold text-slate-500 uppercase tracking-wide">
            {signalRConnected ? 'SignalR: Trß╗▒c tuyß║┐n' : 'Chß║┐ ─æß╗Ö m├┤ phß╗Ång (Simulation)'}
          </span>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Map column */}
        <div className="lg:col-span-2 space-y-4">
          <div className="bg-white p-6 rounded-2xl border border-slate-200/80 shadow-sm space-y-4">
            <h3 className="font-heading font-bold text-slate-900 flex items-center gap-2 text-base">
              <span>≡ƒù║∩╕Å</span> S╞í ─æß╗ô l╞░ß╗¢i nh├á kho (Grid Map 10x10)
            </h3>

            {/* Grid wrapper */}
            <div className="relative border border-slate-200/60 rounded-xl p-4 bg-slate-50/50 overflow-auto flex justify-center">
              <div 
                className="grid gap-1.5"
                style={{ 
                  gridTemplateColumns: `repeat(${gridCols}, minmax(44px, 1fr))`,
                  gridTemplateRows: `repeat(${gridRows}, minmax(44px, 1fr))`
                }}
              >
                {Array.from({ length: gridRows * gridCols }).map((_, idx) => {
                  const x = idx % gridCols;
                  const y = Math.floor(idx / gridCols);

                  // Entity checking
                  const isShelf = shelves.some(s => s.x === x && s.y === y);
                  const activeRobot = robots.find(r => r.x === x && r.y === y);
                  const isCharging = chargingDocks.some(c => c.x === x && c.y === y);
                  const station = deliveryStations.find(s => s.x === x && s.y === y);

                  return (
                    <div
                      key={idx}
                      className={`relative w-11 h-11 rounded-lg border font-mono text-[9px] flex flex-col items-center justify-center transition-all select-none ${
                        isShelf ? 'bg-slate-200 border-slate-300 text-slate-700 font-bold' :
                        isCharging ? 'bg-amber-50 border-amber-200 text-amber-700' :
                        station ? 'bg-blue-50 border-blue-200 text-blue-700 font-bold cursor-pointer hover:bg-blue-100' :
                        'bg-white border-slate-200/60 text-slate-400 hover:bg-slate-105'
                      }`}
                      title={station ? station.name : `Tß╗ìa ─æß╗Ö: (${x}, ${y})`}
                      onClick={() => {
                        if (station && selectedRobot) {
                          commandRobotToMove(station.x, station.y, station.name);
                        }
                      }}
                    >
                      {/* Grid index coords */}
                      {!activeRobot && !isShelf && !station && !isCharging && (
                        <span>{x},{y}</span>
                      )}

                      {/* Charging dock icon */}
                      {isCharging && !activeRobot && <span>ΓÜí</span>}

